3const ThemeContext = createContext(null)
4
5export function ThemeProvider({ children }) {
6  const [theme, setTheme] = useState('light')
7
8  useEffect(function () {
9    document.documentElement.setAttribute('data-theme', theme)
10  }, [theme])
11
12  function toggleTheme() {
13    setTheme(function (t) { return t === 'light' ? 'dark' : 'light' })
14  }
15
16  return (
17    <ThemeContext.Provider value={{ theme, toggleTheme }}>
18      {children}
19    </ThemeContext.Provider>
20  )
21}
22
23export function useTheme() {
24  return useContext(ThemeContext)
25}
